# Minimal par-level inventory: reorder when on-hand falls below par.
from dataclasses import dataclass

@dataclass
class Item:
    name: str
    supplier: str
    par: float      # target stock level
    on_hand: float
    unit_cost: float

def order_list(items):
    orders = {}
    for it in items:
        if it.on_hand < it.par:
            qty = it.par - it.on_hand
            orders.setdefault(it.supplier, []).append((it.name, qty, qty * it.unit_cost))
    return orders

if __name__ == "__main__":
    items = [
        Item("Chicken thigh (lb)", "Valley Foods", 40, 18, 2.10),
        Item("Rice (lb)", "Valley Foods", 60, 55, 0.85),
        Item("Limes (ct)", "Produce Co", 50, 12, 0.30),
    ]
    for sup, lines in order_list(items).items():
        print(sup)
        for name, qty, cost in lines:
            print(f"  {name}: order {qty:g} (${cost:.2f})")
EOF
