# Restaurant waitlist + table turn tracker (prototype for customer interviews)
import time

class Waitlist:
    def __init__(self):
        self.parties = []
    def add(self, name, size):
        self.parties.append({"name": name, "size": size, "added": time.time()})
    def seat_next(self, free_seats):
        for i, p in enumerate(self.parties):
            if p["size"] <= free_seats:
                return self.parties.pop(i)
        return None
    def quoted_wait_minutes(self, position, avg_turn_min=60):
        return round(position * avg_turn_min / 4)

if __name__ == "__main__":
    w = Waitlist()
    w.add("Lee", 2); w.add("Garcia", 4); w.add("Chen", 2)
    print("Seated:", w.seat_next(2)["name"])
    print("Next quoted wait (min):", w.quoted_wait_minutes(len(w.parties)))
EOF
